<?php
require_once __DIR__ . '/../app/layout.php';
$u=require_role(['admin','restaurant','event_organizer','ngo','volunteer']);$pdo=db();
$deliveryId=(int)($_GET['delivery_id']??0);$args=[];$where='1=1';
if($u['role']==='volunteer'){$where='d.volunteer_id=?';$args[]=$u['id'];}
elseif(in_array($u['role'],['restaurant','event_organizer'],true)){$where='sf.restaurant_id=?';$args[]=$u['id'];}
elseif($u['role']==='ngo'){$where='dr.requested_by=?';$args[]=$u['id'];}
if($deliveryId>0){$where.=' AND d.id=?';$args[]=$deliveryId;}
$q=$pdo->prepare("SELECT d.id,d.status,d.created_at,sf.food_name,donor.name AS donor,recipient.name AS recipient FROM deliveries d JOIN donation_requests dr ON dr.id=d.donation_request_id JOIN surplus_food sf ON sf.id=dr.surplus_food_id JOIN users donor ON donor.id=sf.restaurant_id JOIN users recipient ON recipient.id=dr.requested_by WHERE $where ORDER BY d.created_at DESC LIMIT 100");$q->execute($args);$deliveries=$q->fetchAll();
$events=[];if($deliveryId>0){$visible=false;foreach($deliveries as $delivery){if((int)$delivery['id']===$deliveryId){$visible=true;break;}}if($visible){try{$ev=$pdo->prepare("SELECT h.status,h.note,h.created_at,u.name AS actor FROM delivery_status_history h JOIN users u ON u.id=h.changed_by WHERE h.delivery_id=? ORDER BY h.created_at,h.id");$ev->execute([$deliveryId]);$events=$ev->fetchAll();$hashQ=$pdo->prepare('SELECT event_type,event_note,actor_id,previous_hash,event_hash,created_at FROM chain_events WHERE delivery_id=? ORDER BY id');$hashQ->execute([$deliveryId]);$hashEvents=$hashQ->fetchAll();}catch(Throwable $ignored){$hashEvents=[];}}}else{$hashEvents=[];}
page_header('Donation chain of custody'); ?>
<div class="page-intro"><div class="eyebrow">TRACEABILITY</div><h1>Donation <em>journey.</em></h1><p>Review delivery status history for the food handover chain. Existing status records are shown as recorded; hash-linked integrity events begin only after the new migration and code update are active.</p></div>
<div class="table-wrap"><table><thead><tr><th>Delivery</th><th>Food</th><th>Donor</th><th>Recipient</th><th>Status</th><th>Trace</th></tr></thead><tbody><?php foreach($deliveries as $d): ?><tr><td>#<?= (int)$d['id'] ?></td><td><?= e($d['food_name']) ?></td><td><?= e($d['donor']) ?></td><td><?= e($d['recipient']) ?></td><td><?= status_badge($d['status']) ?></td><td><a class="btn btn-sm btn-light" href="<?= e(url('chain_of_custody.php?delivery_id='.(int)$d['id'])) ?>">View history</a></td></tr><?php endforeach; if(!$deliveries): ?><tr><td colspan="6" class="table-empty">No deliveries visible for this account.</td></tr><?php endif; ?></tbody></table></div>
<?php if($deliveryId>0): ?><section class="section"><h2>Delivery #<?= $deliveryId ?> event history</h2><div class="delivery-list"><?php foreach($events as $ev): ?><article class="delivery-card"><div class="delivery-top"><strong><?= e(ucwords(str_replace('_',' ',$ev['status']))) ?></strong><small><?= e(date('d M Y, g:i A',strtotime($ev['created_at']))) ?></small></div><p><?= e($ev['note']??'') ?></p><small class="table-sub">Recorded by <?= e($ev['actor']) ?></small></article><?php endforeach; if(!$events): ?><p>No status history has been recorded for this delivery yet.</p><?php endif; ?></div><?php if(!empty($hashEvents)): ?><h3>Hash-linked integrity events</h3><div class="table-wrap"><table><thead><tr><th>Event</th><th>Timestamp</th><th>Previous hash</th><th>Event hash</th></tr></thead><tbody><?php $expectedPrevious=null; foreach($hashEvents as $he): $canonical=implode("\n",[$deliveryId,(string)$he['event_type'],(int)$he['actor_id'],(string)($he['event_note']??''),(string)$he['created_at'],$expectedPrevious??'']); $computed=hash('sha256',$canonical); $valid=hash_equals((string)$he['event_hash'],$computed) && (($he['previous_hash']??null)===$expectedPrevious); ?><tr><td><?= e($he['event_type']) ?> <?= $valid ? status_badge('verified') : status_badge('flagged') ?></td><td><?= e($he['created_at']) ?></td><td><code><?= e($he['previous_hash']??'GENESIS') ?></code></td><td><code><?= e($he['event_hash']) ?></code></td></tr><?php $expectedPrevious=$he['event_hash']; endforeach; ?></tbody></table></div><p class="table-sub">Hashes are tamper-evident checks, not a guarantee against a privileged database administrator.</p><?php endif; ?></section><?php endif; ?>
<?php page_footer(); ?>
